#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int u, v;
} Edge;

typedef struct {
    int to, next;
} Adj;

static int max(int a, int b) { return a > b ? a : b; }

int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;

    while (T--) {
        int n, m;
        scanf("%d %d", &n, &m);

        Edge *edges = (Edge *)malloc((size_t)m * sizeof(Edge));
        Adj *adj = (Adj *)malloc((size_t)(2 * m) * sizeof(Adj));
        int *head = (int *)malloc((size_t)(n + 1) * sizeof(int));
        int *deg = (int *)calloc((size_t)(n + 1), sizeof(int));
        int *vis = (int *)calloc((size_t)(n + 1), sizeof(int));

        for (int i = 1; i <= n; i++) head[i] = -1;

        int ecnt = 0;
        for (int i = 0; i < m; i++) {
            int u, v;
            long long w;
            scanf("%d %d %lld", &u, &v, &w);
            edges[i].u = u;
            edges[i].v = v;

            adj[ecnt].to = v;
            adj[ecnt].next = head[u];
            head[u] = ecnt++;
            adj[ecnt].to = u;
            adj[ecnt].next = head[v];
            head[v] = ecnt++;

            deg[u]++;
            deg[v]++;
        }

        int components = 0;
        int *queue = (int *)malloc((size_t)(n + 5) * sizeof(int));

        for (int s = 1; s <= n; s++) {
            if (vis[s] || deg[s] == 0) continue;
            components++;
            int qh = 0, qt = 0;
            queue[qt++] = s;
            vis[s] = 1;
            while (qh < qt) {
                int u = queue[qh++];
                for (int e = head[u]; e != -1; e = adj[e].next) {
                    int v = adj[e].to;
                    if (!vis[v]) {
                        vis[v] = 1;
                        queue[qt++] = v;
                    }
                }
            }
        }

        /*
          For each weakly connected component, one flow-conservation equation is redundant.
          So rank = (#vertices with nonzero degree) - (#weakly connected components).
          Minimum number of edges to keep = m - rank
                                      = m - (Vnz - C)
                                      = m - Vnz + C
          Since isolated vertices do not appear in any edge, Vnz is the number of vertices
          with positive degree.
        */
        int vertices_nonzero = 0;
        for (int i = 1; i <= n; i++) {
            if (deg[i] > 0) vertices_nonzero++;
        }

        int answer = m - vertices_nonzero + components;
        printf("%d\n", answer);

        free(edges);
        free(adj);
        free(head);
        free(deg);
        free(vis);
        free(queue);
    }

    return 0;
}

