            u--; v--;
            adj[u].push_back(v);
            adj[v].push_back(u); // undirected for connectivity
        }

        vector<bool> visited(n, false);
        int total_keep = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                // BFS/DFS to find component
                queue<int> q;
                q.push(i);
                visited[i] = true;
                int nodes = 0, edges = 0;
                while (!q.empty()) {
                    int u = q.front(); q.pop();
                    nodes++;
                    for (int v : adj[u]) {
                        edges++;
                        if (!visited[v]) {
                            visited[v] = true;
                            q.push(v);
                        }
                    }
                }
                edges /= 2; // each edge counted twice
                total_keep += nodes; // keep exactly nodes edges
            }
        }
        cout << m - total_keep << "\n";
    }
    return 0;
}

