#include <bits/stdc++.h>
using namespace std;

/*
We need the minimum number of edges to keep so that all erased edge values
are uniquely recoverable from flow conservation at every node.

Let m = number of edges, n = number of vertices.
Flow conservation gives linear equations B * x = 0, where B is the
vertex-edge incidence matrix of the underlying directed graph:
for each edge e = u -> v, column e has -1 at u and +1 at v.

If we keep a subset K of edge values known, then unknown edges U are
recoverable iff the subsystem B_U * x_U = known_rhs has a unique solution,
i.e. columns of B_U are linearly independent.

Thus we want to maximize number of erasable edges = maximum size of a set
of columns of B that is independent. The minimum kept edges is:
    m - rank(B)

For a graph with c weakly connected components (equivalently connected
components of the underlying undirected graph), rank(B) = n - c.
Therefore answer = m - (n - c) = m - n + c.

So for each test case, we only need to count connected components in the
underlying undirected graph.
*/

struct DSU {
    vector<int> p, sz;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n + 1);
        sz.assign(n + 1, 1);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n, m;
        cin >> n >> m;
        DSU dsu(n);
        for (int i = 0; i < m; ++i) {
            int u, v;
            long long w;
            cin >> u >> v >> w; // value itself is irrelevant for the answer
            dsu.unite(u, v);
        }

        int comps = 0;
        for (int i = 1; i <= n; ++i) {
            if (dsu.find(i) == i) ++comps;
        }

        cout << (m - n + comps) << '\n';
    }
    return 0;
}

import java.io.*;
import java.util.*;

public class Solution {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(" ");
            int n = Integer.parseInt(parts[0]);
            int m = Integer.parseInt(parts[1]);
            if (n == 0 && m == 0) break;

            // Build graph for connectivity
            List<Integer>[] adj = new ArrayList[n];
            for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                parts = br.readLine().split(" ");
                int u = Integer.parseInt(parts[0]);
                int v = Integer.parseInt(parts[1]);
                // value not needed for connectivity
                adj[u].add(v);
                adj[v].add(u);
            }

            boolean[] visited = new boolean[n];
            int components = 0;
            for (int i = 0; i < n; i++) {
                if (!visited[i]) {
                    components++;
                    Queue<Integer> q = new LinkedList<>();
                    q.add(i);
                    visited[i] = true;
                    while (!q.isEmpty()) {
                        int u = q.poll();
                        for (int v : adj[u]) {
                            if (!visited[v]) {
                                visited[v] = true;
                                q.add(v);
                            }
                        }
                    }
                }
            }

            sb.append(n - components).append("\n");
        }

        System.out.print(sb.toString());
    }
}

