import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class DSU {
        int[] p, r;
        DSU(int n) {
            p = new int[n];
            r = new int[n];
            for (int i = 0; i < n; i++) p[i] = i;
        }
        int find(int x) {
            if (p[x] != x) p[x] = find(p[x]);
            return p[x];
        }
        boolean union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return false;
            if (r[a] < r[b]) {
                int t = a; a = b; b = t;
            }
            p[b] = a;
            if (r[a] == r[b]) r[a]++;
            return true;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        int T = fs.nextInt();
        while (T-- > 0) {
            int n = fs.nextInt();
            int m = fs.nextInt();

            DSU dsu = new DSU(n);
            boolean[] used = new boolean[n];

            for (int i = 0; i < m; i++) {
                int u = fs.nextInt() - 1;
                int v = fs.nextInt() - 1;
                dsu.union(u, v); // underlying undirected connectivity
                used[u] = true;
                used[v] = true;
            }

            HashSet<Integer> comps = new HashSet<>();
            for (int i = 0; i < n; i++) {
                if (used[i]) comps.add(dsu.find(i));
            }

            int c = comps.size();
            int answer = m - n + c; // cycle space dimension of each connected component summed
            out.append(answer).append('\n');
        }

        System.out.print(out.toString());
    }
}
